use vstd::prelude::*;

verus! {
    fn solve(t: Vec<char>) -> (output: Vec<char>)
        requires
            t.len() < 0x1_0000_0000, // Ensure the length of the input vector is within bounds
        ensures
            output.len() == t.len() && forall |i: nat| 0 <= i < t.len() ==> output[i] == t[i], // Ensure output has the same length and elements as input
    {
        let mut output = Vec::with_capacity(t.len()); // Preallocate memory for efficiency
        let mut index = 0; // Initialize index to track the position in the input vector

        // Loop through the input vector
        while index < t.len()
            invariant
                index <= t.len(), // Ensure index does not exceed the length of the input vector
                output.len() == index, // Ensure output length matches the current index
                forall |i: nat| 0 <= i < index ==> output[i] == t[i], // Ensure output matches input up to the current index
            decreases t.len() - index, // Decrease clause to ensure termination
        {
            output.push(t[index]); // Append the current character to the output
            index += 1; // Move to the next index
        }

        output // Return the constructed output vector
    }
}

